/**
 * Wire format for a conversation checkpoint pack: many content-addressed
 * checkpoint blobs in one durable object, so a turn's new blobs cost one
 * store write instead of one per blob.
 *
 * Layout (big-endian): the 8-byte magic, a u32 entry count, then per entry a
 * u16 blob-id length, the UTF-8 blob id, a u32 data length and the data. The
 * pack id is the SHA-256 of the whole encoding, so a pack is immutable and
 * a re-upload after a failed persist lands on the same key.
 */
import { createHash } from "node:crypto";
const MAGIC = new TextEncoder().encode("BDKCPK1\n");
const MAX_BLOB_ID_BYTES = 0xffff;
const MAX_ENTRY_BYTES = 0xffffffff;
/** Bytes an entry adds to a pack; used to split packs before encoding. */
export function conversationPackEntrySize(entry) {
    return 2 + new TextEncoder().encode(entry.blobId).length + 4 + entry.data.length;
}
export function conversationPackId(body) {
    return createHash("sha256").update(body).digest("hex");
}
export function encodeConversationPack(entries) {
    const encoder = new TextEncoder();
    const ids = entries.map((entry) => encoder.encode(entry.blobId));
    let size = MAGIC.length + 4;
    for (const [index, entry] of entries.entries()) {
        const id = ids[index];
        if (id.length === 0 || id.length > MAX_BLOB_ID_BYTES) {
            throw new Error(`conversation pack: blob id "${entry.blobId}" has an unencodable length`);
        }
        if (entry.data.length > MAX_ENTRY_BYTES) {
            throw new Error(`conversation pack: blob "${entry.blobId}" is too large to pack`);
        }
        size += 2 + id.length + 4 + entry.data.length;
    }
    const body = new Uint8Array(size);
    const view = new DataView(body.buffer);
    body.set(MAGIC, 0);
    let offset = MAGIC.length;
    view.setUint32(offset, entries.length);
    offset += 4;
    for (const [index, entry] of entries.entries()) {
        const id = ids[index];
        view.setUint16(offset, id.length);
        offset += 2;
        body.set(id, offset);
        offset += id.length;
        view.setUint32(offset, entry.data.length);
        offset += 4;
        body.set(entry.data, offset);
        offset += entry.data.length;
    }
    return { packId: conversationPackId(body), body };
}
/**
 * Decode a pack read back from the store. Throws on any structural damage or
 * when the bytes do not hash to `packId`; the caller treats that exactly like
 * a missing pack.
 */
export function decodeConversationPack(packId, body) {
    if (conversationPackId(body) !== packId) {
        throw new Error("conversation pack: content does not match its id");
    }
    if (body.length < MAGIC.length + 4 || MAGIC.some((byte, index) => body[index] !== byte)) {
        throw new Error("conversation pack: unrecognized format");
    }
    const view = new DataView(body.buffer, body.byteOffset, body.byteLength);
    const decoder = new TextDecoder("utf-8", { fatal: true });
    let offset = MAGIC.length;
    const count = view.getUint32(offset);
    offset += 4;
    const entries = [];
    const need = (bytes) => {
        if (offset + bytes > body.length) {
            throw new Error("conversation pack: truncated");
        }
    };
    for (let index = 0; index < count; index++) {
        need(2);
        const idLength = view.getUint16(offset);
        offset += 2;
        need(idLength);
        const blobId = decoder.decode(body.subarray(offset, offset + idLength));
        offset += idLength;
        need(4);
        const dataLength = view.getUint32(offset);
        offset += 4;
        need(dataLength);
        entries.push({ blobId, data: body.slice(offset, offset + dataLength) });
        offset += dataLength;
    }
    if (offset !== body.length) {
        throw new Error("conversation pack: trailing bytes");
    }
    return entries;
}
